update team_application
set status = '승인', processed_at = now()
where application_id = #{applicationId}
  and team_id = #{teamId}
  and status = '승인 대기'

update team_application
set status = '거절', processed_at = now(), rejection_reason = #{reason}
where application_id = #{applicationId}
  and team_id = #{teamId}
  and status = '승인 대기'

mapper.select:
SELECT a.application_id AS applicationId, a.team_id AS teamId, a.status, DATE_FORMAT(a.applied_at, '%Y-%m-%d %H:%i') AS appliedAt, a.message AS description, t.team_name AS teamName, t.sport from team_application a join team t on t.team_id = a.team_id where a.user_id = #{userId} and a.status = '승인 대기'
AND t.sport = #{sport}
AND a.status = #{status}
ORDER BY a.applied_at DESC, a.application_id DESC LIMIT #{size} OFFSET #{offset}

select count(*)
from team_application a
where a.user_id = #{userId} and
a.status = '승인 대기'

	AND t.sport = #{sport}


	AND a.status = #{status}

